#include "parser.hpp"
#include <algorithm>
#include <cerrno>
#include <cstdlib>
#include <set>
#include "error.hpp"
#include "util.hpp"

namespace {
	std::string lower(std::string text)
	{
		std::transform(text.cbegin(), text.cend(), text.begin(), blitz::utility::utf8_safe_tolower);
		return text;
	}

	// Words that can never be used as a variable or function name.
	const std::set<std::string> reserved = {
		"then",  "to",     "step",   "else",    "elseif", "endif",     "end",    "wend",  "next", "until", "forever", "case",
		"default", "local", "global", "const",   "if",     "while",     "repeat", "for",   "select", "function", "endfunction", "endselect",
		"return", "exit",  "include", "dim",    "type",   "and",       "or",     "xor",   "mod",  "shl",   "shr",     "sar",
		"not",    "goto",   "gosub",  "dim",    "type",   "endtype", "field", "new",  "delete", "insert", "before", "after", "each", "first", "last",
	};

	// Things that exist in Blitz, but that we do not (yet) know how to compile.
	const std::set<std::string> unsupported = {
		"data", "read", "restore",
	};
} // namespace

blitz::parser::~parser() {}

blitz::parser::parser() : _file(), _file_ptr(), _tokens(), _pos(0), _include_stack(), _program(), _depth(0) {}

std::unique_ptr<blitz::ast::program> blitz::parser::parse(std::filesystem::path file)
{
	_program = std::make_unique<ast::program>();
	_include_stack.clear();
	_depth = 0;
	parse_file(file, _program->main);
	return std::move(_program);
}

////////////////////////////////////////////////////////////////////////////////
// Token handling
////////////////////////////////////////////////////////////////////////////////
blitz::token const& blitz::parser::tk(size_t offset) const
{
	size_t idx = std::min(_pos + offset, _tokens.size() - 1); // The last token is always EndOfFile.
	return _tokens[idx];
}

void blitz::parser::advance()
{
	if (_pos < _tokens.size() - 1) {
		_pos++;
	}
}

blitz::ast::location blitz::parser::here(blitz::token const& token) const
{
	return ast::location{ _file_ptr, token.location.first, token.location.second };
}

blitz::error blitz::parser::error(blitz::token const& token, std::string const& reason) const
{
	return blitz::error(_file, token.location, token.location, reason);
}

bool blitz::parser::is_keyword(blitz::token const& token, const char* keyword) const
{
	return (token.type == blitz::token::variant::TEXT) && (lower(token.text) == keyword);
}

bool blitz::parser::is_symbol(blitz::token const& token, const char* symbol) const
{
	return (token.type == blitz::token::variant::SYMBOL) && (token.text == symbol);
}

bool blitz::parser::is_terminator(blitz::token const& token) const
{
	return (token.type == blitz::token::variant::NEWLINE) || (token.type == blitz::token::variant::SEPARATOR) || (token.type == blitz::token::variant::ENDOFFILE) || is_keyword(token, "else");
}

bool blitz::parser::adjacent(blitz::token const& lhs, blitz::token const& rhs) const
{
	return (lhs.location.first == rhs.location.first) && ((lhs.location.second + lhs.text.length()) == rhs.location.second);
}

void blitz::parser::skip_empty()
{
	while ((tk().type == blitz::token::variant::NEWLINE) || (tk().type == blitz::token::variant::SEPARATOR)) {
		advance();
	}
}

void blitz::parser::expect_keyword(const char* keyword)
{
	if (!is_keyword(tk(), keyword)) {
		throw error(tk(), blitz::format("Unexpected %s, expected '%s'.", tk().to_string().c_str(), keyword));
	}
	advance();
}

void blitz::parser::expect_symbol(const char* symbol)
{
	if (!is_symbol(tk(), symbol)) {
		throw error(tk(), blitz::format("Unexpected %s, expected '%s'.", tk().to_string().c_str(), symbol));
	}
	advance();
}

////////////////////////////////////////////////////////////////////////////////
// Files
////////////////////////////////////////////////////////////////////////////////
void blitz::parser::load(std::filesystem::path file)
{
	_file     = file;
	_file_ptr = std::make_shared<const std::filesystem::path>(file);
	_tokens.clear();
	_pos = 0;

	blitz::lexer lex(file);
	while (true) {
		auto token = lex.next();
		if (token.type == blitz::token::variant::COMMENT) {
			continue;
		}
		_tokens.push_back(token);
		if (token.type == blitz::token::variant::ENDOFFILE) {
			break;
		}
	}
}

void blitz::parser::parse_file(std::filesystem::path file, ast::block& into)
{
	std::error_code ec;
	auto            canonical = std::filesystem::weakly_canonical(file, ec);
	if (std::find(_include_stack.begin(), _include_stack.end(), canonical) != _include_stack.end()) {
		throw blitz::error(_file, { 0, 0 }, { 0, 0 }, blitz::format("Recursive include of '%s'.", file.generic_string().c_str()));
	}
	_include_stack.push_back(canonical);

	// Includes interrupt the parsing of the current file, so we have to restore it afterwards.
	auto saved_file   = _file;
	auto saved_ptr    = _file_ptr;
	auto saved_tokens = std::move(_tokens);
	auto saved_pos    = _pos;

	load(file);
	while (true) {
		skip_empty();
		if (tk().type == blitz::token::variant::ENDOFFILE) {
			break;
		}
		if (at_block_end()) {
			throw error(tk(), blitz::format("Unexpected %s.", tk().to_string().c_str()));
		}
		parse_statement(into);
		if ((tk().type == blitz::token::variant::NEWLINE) || (tk().type == blitz::token::variant::SEPARATOR)) {
			advance();
		} else if (tk().type != blitz::token::variant::ENDOFFILE) {
			throw error(tk(), blitz::format("Unexpected %s, expected end of statement.", tk().to_string().c_str()));
		}
	}

	_file     = saved_file;
	_file_ptr = saved_ptr;
	_tokens   = std::move(saved_tokens);
	_pos      = saved_pos;
	_include_stack.pop_back();
}

////////////////////////////////////////////////////////////////////////////////
// Statements
////////////////////////////////////////////////////////////////////////////////
bool blitz::parser::at_block_end() const
{
	auto const& t = tk();
	if (t.type == blitz::token::variant::ENDOFFILE) {
		return true;
	}
	if (t.type != blitz::token::variant::TEXT) {
		return false;
	}
	for (auto word : { "wend", "next", "until", "forever", "endif", "else", "elseif", "case", "default", "endselect", "endfunction" }) {
		if (is_keyword(t, word)) {
			return true;
		}
	}
	if (is_keyword(t, "end")) {
		auto const& n = tk(1);
		return is_keyword(n, "if") || is_keyword(n, "select") || is_keyword(n, "function");
	}
	return false;
}

void blitz::parser::expect_block_end(const char* single, const char* first, const char* second)
{
	if (is_keyword(tk(), single)) {
		advance();
	} else if (is_keyword(tk(), first) && is_keyword(tk(1), second)) {
		advance();
		advance();
	} else {
		throw error(tk(), blitz::format("Unexpected %s, expected '%s'.", tk().to_string().c_str(), single));
	}
}

void blitz::parser::parse_block(ast::block& into)
{
	_depth++;
	while (true) {
		skip_empty();
		if (at_block_end()) {
			break;
		}
		parse_statement(into);
		if ((tk().type == blitz::token::variant::NEWLINE) || (tk().type == blitz::token::variant::SEPARATOR)) {
			advance();
		} else if (tk().type != blitz::token::variant::ENDOFFILE) {
			throw error(tk(), blitz::format("Unexpected %s, expected end of statement.", tk().to_string().c_str()));
		}
	}
	_depth--;
}

void blitz::parser::parse_line(ast::block& into)
{
	// Single-line statements, as used by `If x Then a : b Else c`. Ends at the New Line (not consumed) or Else.
	_depth++;
	while (true) {
		parse_statement(into);
		if (tk().type == blitz::token::variant::SEPARATOR) {
			advance();
			if (is_terminator(tk()) && !is_keyword(tk(), "else") && (tk().type != blitz::token::variant::SEPARATOR)) {
				break;
			}
			if (is_keyword(tk(), "else")) {
				break;
			}
			continue;
		}
		if (!is_terminator(tk())) {
			throw error(tk(), blitz::format("Unexpected %s, expected end of statement.", tk().to_string().c_str()));
		}
		break;
	}
	_depth--;
}

void blitz::parser::parse_label(ast::block& into)
{
	auto dot = tk();
	advance();
	auto name = tk();
	advance();
	auto node   = std::make_unique<ast::label_statement>();
	node->where = here(dot);
	node->name  = name.text;
	into.push_back(std::move(node));
}

void blitz::parser::parse_jump(ast::block& into)
{
	auto first  = tk();
	bool gosub  = is_keyword(first, "gosub");
	advance();
	auto label = tk();
	if (label.type != blitz::token::variant::TEXT) {
		throw error(label, blitz::format("Unexpected %s, expected a label name.", label.to_string().c_str()));
	}
	advance();
	if (gosub) {
		auto node   = std::make_unique<ast::gosub_statement>();
		node->where = here(first);
		node->label = label.text;
		into.push_back(std::move(node));
	} else {
		auto node   = std::make_unique<ast::goto_statement>();
		node->where = here(first);
		node->label = label.text;
		into.push_back(std::move(node));
	}
}

void blitz::parser::parse_statement(ast::block& into)
{
	auto const& first = tk();
	if (is_symbol(first, ".") && (tk(1).type == blitz::token::variant::TEXT) && adjacent(first, tk(1))) {
		parse_label(into);
		return;
	}
	if (first.type != blitz::token::variant::TEXT) {
		throw error(first, blitz::format("Unexpected %s, expected a statement.", first.to_string().c_str()));
	}

	std::string word = lower(first.text);
	if ((word == "local") || (word == "global") || (word == "const")) {
		parse_declare(into);
	} else if (word == "if") {
		parse_if(into);
	} else if (word == "while") {
		parse_while(into);
	} else if (word == "repeat") {
		parse_repeat(into);
	} else if (word == "for") {
		parse_for(into);
	} else if (word == "select") {
		parse_select(into);
	} else if (word == "function") {
		parse_function();
	} else if (word == "include") {
		parse_include(into);
	} else if (word == "type") {
		parse_type_decl();
	} else if (word == "dim") {
		parse_dim(into);
	} else if ((word == "goto") || (word == "gosub")) {
		parse_jump(into);
	} else if (word == "delete") {
		parse_delete(into);
	} else if (word == "insert") {
		parse_insert(into);
	} else if (word == "exit") {
		auto node   = std::make_unique<ast::exit_statement>();
		node->where = here(first);
		advance();
		into.push_back(std::move(node));
	} else if (word == "end") {
		auto node   = std::make_unique<ast::end_statement>();
		node->where = here(first);
		advance();
		into.push_back(std::move(node));
	} else if (word == "return") {
		auto node   = std::make_unique<ast::return_statement>();
		node->where = here(first);
		advance();
		if (!is_terminator(tk())) {
			node->value = parse_expression();
		}
		into.push_back(std::move(node));
	} else if (unsupported.count(word)) {
		throw error(first, blitz::format("'%s' is not supported yet.", first.text.c_str()));
	} else if (reserved.count(word)) {
		throw error(first, blitz::format("Unexpected '%s'.", first.text.c_str()));
	} else {
		parse_identifier_statement(into);
	}
}

void blitz::parser::parse_declare(ast::block& into)
{
	auto first = tk();
	auto word  = lower(first.text);
	advance();

	auto node      = std::make_unique<ast::declare>();
	node->where    = here(first);
	node->global   = (word == "global");
	node->constant = (word == "const");

	while (true) {
		auto const& name = tk();
		if ((name.type != blitz::token::variant::TEXT) || reserved.count(lower(name.text))) {
			throw error(name, blitz::format("Unexpected %s, expected a variable name.", name.to_string().c_str()));
		}
		auto name_tk = name;
		advance();

		ast::declaration decl;
		decl.where = here(name_tk);
		decl.name  = name_tk.text;
		decl.type        = parse_type_suffix(name_tk);
		decl.struct_name = _struct_name;
		if (is_symbol(tk(), "[")) {
			advance();
			decl.array_size = parse_expression();
			expect_symbol("]");
		}
		if (is_symbol(tk(), "=")) {
			advance();
			decl.initial = parse_expression();
		} else if (node->constant) {
			throw error(tk(), "Constants require a value.");
		}
		node->variables.push_back(std::move(decl));

		if (is_symbol(tk(), ",")) {
			advance();
			continue;
		}
		break;
	}
	into.push_back(std::move(node));
}

void blitz::parser::parse_if(ast::block& into)
{
	auto first = tk();
	advance();

	auto node   = std::make_unique<ast::if_statement>();
	node->where = here(first);

	ast::branch branch;
	branch.condition = parse_expression();
	if (is_keyword(tk(), "then")) {
		advance();
	}

	if (tk().type == blitz::token::variant::NEWLINE) {
		// Block form
		parse_block(branch.body);
		node->branches.push_back(std::move(branch));

		while (true) {
			if (is_keyword(tk(), "elseif") || (is_keyword(tk(), "else") && is_keyword(tk(1), "if"))) {
				if (is_keyword(tk(), "else")) {
					advance();
				}
				advance();
				ast::branch next;
				next.condition = parse_expression();
				if (is_keyword(tk(), "then")) {
					advance();
				}
				parse_block(next.body);
				node->branches.push_back(std::move(next));
			} else if (is_keyword(tk(), "else")) {
				advance();
				ast::branch next;
				parse_block(next.body);
				node->branches.push_back(std::move(next));
			} else {
				break;
			}
		}
		expect_block_end("endif", "end", "if");
	} else {
		// Single-line form
		parse_line(branch.body);
		node->branches.push_back(std::move(branch));
		if (is_keyword(tk(), "else")) {
			advance();
			ast::branch next;
			parse_line(next.body);
			node->branches.push_back(std::move(next));
		}
	}
	into.push_back(std::move(node));
}

void blitz::parser::parse_while(ast::block& into)
{
	auto first = tk();
	advance();

	auto node       = std::make_unique<ast::while_statement>();
	node->where     = here(first);
	node->condition = parse_expression();
	parse_block(node->body);
	expect_keyword("wend");
	into.push_back(std::move(node));
}

void blitz::parser::parse_repeat(ast::block& into)
{
	auto first = tk();
	advance();

	auto node   = std::make_unique<ast::repeat_statement>();
	node->where = here(first);
	parse_block(node->body);
	if (is_keyword(tk(), "until")) {
		advance();
		node->condition = parse_expression();
	} else {
		expect_keyword("forever");
	}
	into.push_back(std::move(node));
}

void blitz::parser::parse_for(ast::block& into)
{
	auto first = tk();
	advance();

	auto node   = std::make_unique<ast::for_statement>();
	node->where = here(first);

	auto name = tk();
	if ((name.type != blitz::token::variant::TEXT) || reserved.count(lower(name.text))) {
		throw error(name, blitz::format("Unexpected %s, expected a variable name.", name.to_string().c_str()));
	}
	advance();
	node->variable        = std::make_unique<ast::reference>();
	node->variable->where = here(name);
	node->variable->name  = name.text;
	node->variable->type  = parse_type_suffix(name);
	node->variable->struct_name = _struct_name;

	expect_symbol("=");
	if (is_keyword(tk(), "each")) {
		// For v.Type = Each Type
		advance();
		auto type_tk = tk();
		if ((type_tk.type != blitz::token::variant::TEXT) || reserved.count(lower(type_tk.text))) {
			throw error(type_tk, blitz::format("Unexpected %s, expected a type name.", type_tk.to_string().c_str()));
		}
		advance();
		node->each_type = type_tk.text;
		parse_block(node->body);
		expect_keyword("next");
		if ((tk().type == blitz::token::variant::TEXT) && !is_keyword(tk(), "else")) {
			auto var = tk();
			advance();
			parse_type_suffix(var);
		}
		into.push_back(std::move(node));
		return;
	}
	node->from = parse_expression();
	expect_keyword("to");
	node->to = parse_expression();
	if (is_keyword(tk(), "step")) {
		advance();
		node->step = parse_expression();
	}

	parse_block(node->body);
	expect_keyword("next");
	// `Next I` is allowed, the name is optional and not checked.
	if ((tk().type == blitz::token::variant::TEXT) && !is_keyword(tk(), "else")) {
		auto var = tk();
		advance();
		parse_type_suffix(var);
	}
	into.push_back(std::move(node));
}

void blitz::parser::parse_select(ast::block& into)
{
	auto first = tk();
	advance();

	auto node     = std::make_unique<ast::select_statement>();
	node->where   = here(first);
	node->subject = parse_expression();
	skip_empty();

	while (true) {
		skip_empty();
		if (is_keyword(tk(), "case")) {
			advance();
			ast::select_case entry;
			while (true) {
				entry.values.push_back(parse_expression());
				if (is_symbol(tk(), ",")) {
					advance();
					continue;
				}
				break;
			}
			parse_block(entry.body);
			node->cases.push_back(std::move(entry));
		} else if (is_keyword(tk(), "default")) {
			advance();
			ast::select_case entry;
			parse_block(entry.body);
			node->cases.push_back(std::move(entry));
		} else {
			break;
		}
	}
	expect_block_end("endselect", "end", "select");
	into.push_back(std::move(node));
}

void blitz::parser::parse_function()
{
	auto first = tk();
	if (_depth != 0) {
		throw error(first, "Functions can't be defined inside of other blocks.");
	}
	advance();

	auto name = tk();
	if ((name.type != blitz::token::variant::TEXT) || reserved.count(lower(name.text))) {
		throw error(name, blitz::format("Unexpected %s, expected a function name.", name.to_string().c_str()));
	}
	advance();

	auto fn   = std::make_unique<ast::function>();
	fn->where = here(first);
	fn->name  = name.text;
	fn->type  = parse_type_suffix(name);
	fn->struct_name = _struct_name;
	if (fn->type == blitz::types::type::UNKNOWN) {
		fn->type = blitz::types::type::INT32;
	}

	expect_symbol("(");
	if (!is_symbol(tk(), ")")) {
		while (true) {
			auto pname = tk();
			if ((pname.type != blitz::token::variant::TEXT) || reserved.count(lower(pname.text))) {
				throw error(pname, blitz::format("Unexpected %s, expected a parameter name.", pname.to_string().c_str()));
			}
			advance();

			ast::parameter param;
			param.where = here(pname);
			param.name  = pname.text;
			param.type  = parse_type_suffix(pname);
			param.struct_name = _struct_name;
			if (param.type == blitz::types::type::UNKNOWN) {
				param.type = blitz::types::type::INT32;
			}
			if (is_symbol(tk(), "=")) {
				advance();
				param.initial = parse_expression();
			}
			fn->parameters.push_back(std::move(param));

			if (is_symbol(tk(), ",")) {
				advance();
				continue;
			}
			break;
		}
	}
	expect_symbol(")");

	parse_block(fn->body);
	expect_block_end("endfunction", "end", "function");
	_program->functions.push_back(std::move(fn));
}

void blitz::parser::parse_include(ast::block& into)
{
	advance();
	auto file_tk = tk();
	if (file_tk.type != blitz::token::variant::STRING) {
		throw error(file_tk, blitz::format("Unexpected %s, expected a file name in quotes.", file_tk.to_string().c_str()));
	}
	advance();

	// Includes are relative to the file that includes them.
	std::filesystem::path target = std::filesystem::path(file_tk.text);
	if (target.is_relative()) {
		target = _file.parent_path() / target;
	}
	if (!std::filesystem::exists(target)) {
		throw error(file_tk, blitz::format("Included file '%s' does not exist.", file_tk.text.c_str()));
	}
	parse_file(target, into);
}

void blitz::parser::parse_type_decl()
{
	auto first = tk();
	if (_depth != 0) {
		throw error(first, "Types can't be defined inside of other blocks.");
	}
	advance();

	auto name = tk();
	if ((name.type != blitz::token::variant::TEXT) || reserved.count(lower(name.text))) {
		throw error(name, blitz::format("Unexpected %s, expected a type name.", name.to_string().c_str()));
	}
	advance();

	auto decl   = std::make_unique<ast::type_decl>();
	decl->where = here(first);
	decl->name  = name.text;

	while (true) {
		skip_empty();
		if (is_keyword(tk(), "endtype")) {
			advance();
			break;
		} else if (is_keyword(tk(), "end") && is_keyword(tk(1), "type")) {
			advance();
			advance();
			break;
		} else if (!is_keyword(tk(), "field")) {
			throw error(tk(), blitz::format("Unexpected %s, expected 'Field' or 'End Type'.", tk().to_string().c_str()));
		}
		advance();

		while (true) {
			auto fname = tk();
			if (fname.type != blitz::token::variant::TEXT) {
				throw error(fname, blitz::format("Unexpected %s, expected a field name.", fname.to_string().c_str()));
			}
			advance();

			ast::field_decl field;
			field.where       = here(fname);
			field.name        = fname.text;
			field.type        = parse_type_suffix(fname);
			field.struct_name = _struct_name;
			if (field.type == blitz::types::type::UNKNOWN) {
				field.type = blitz::types::type::INT32;
			}
			if (is_symbol(tk(), "[")) {
				advance();
				field.array_size = parse_expression();
				expect_symbol("]");
			}
			decl->fields.push_back(std::move(field));

			if (is_symbol(tk(), ",")) {
				advance();
				continue;
			}
			break;
		}
	}
	_program->types.push_back(std::move(decl));
}

void blitz::parser::parse_dim(ast::block& into)
{
	auto first = tk();
	advance();

	auto node   = std::make_unique<ast::dim_statement>();
	node->where = here(first);
	while (true) {
		auto name = tk();
		if ((name.type != blitz::token::variant::TEXT) || reserved.count(lower(name.text))) {
			throw error(name, blitz::format("Unexpected %s, expected an array name.", name.to_string().c_str()));
		}
		advance();

		ast::dim_declaration decl;
		decl.where       = here(name);
		decl.name        = name.text;
		decl.type        = parse_type_suffix(name);
		decl.struct_name = _struct_name;
		if (decl.type == blitz::types::type::UNKNOWN) {
			decl.type = blitz::types::type::INT32;
		}
		expect_symbol("(");
		while (true) {
			decl.sizes.push_back(parse_expression());
			if (is_symbol(tk(), ",")) {
				advance();
				continue;
			}
			break;
		}
		expect_symbol(")");
		if (decl.sizes.size() > 4) {
			throw error(name, "Arrays can have up to 4 dimensions.");
		}
		node->arrays.push_back(std::move(decl));

		if (is_symbol(tk(), ",")) {
			advance();
			continue;
		}
		break;
	}
	into.push_back(std::move(node));
}

void blitz::parser::parse_delete(ast::block& into)
{
	auto first = tk();
	advance();

	auto node   = std::make_unique<ast::delete_statement>();
	node->where = here(first);
	if (is_keyword(tk(), "each")) {
		advance();
		auto type_tk = tk();
		if (type_tk.type != blitz::token::variant::TEXT) {
			throw error(type_tk, blitz::format("Unexpected %s, expected a type name.", type_tk.to_string().c_str()));
		}
		advance();
		node->each_type = type_tk.text;
	} else {
		node->object = parse_expression();
	}
	into.push_back(std::move(node));
}

void blitz::parser::parse_insert(ast::block& into)
{
	auto first = tk();
	advance();

	auto node    = std::make_unique<ast::insert_statement>();
	node->where  = here(first);
	node->object = parse_unary();
	if (is_keyword(tk(), "before")) {
		node->after = false;
	} else if (is_keyword(tk(), "after")) {
		node->after = true;
	} else {
		throw error(tk(), blitz::format("Unexpected %s, expected 'Before' or 'After'.", tk().to_string().c_str()));
	}
	advance();
	node->other = parse_unary();
	into.push_back(std::move(node));
}

void blitz::parser::parse_identifier_statement(ast::block& into)
{
	auto name  = tk();
	size_t start = _pos;

	// Assignment: the left side can be a variable, a field, or an array element.
	try {
		auto target = parse_primary();
		if (is_symbol(tk(), "=")) {
			auto node    = std::make_unique<ast::assign>();
			node->where  = here(name);
			node->target = std::move(target);
			advance();
			node->value = parse_expression();
			into.push_back(std::move(node));
			return;
		}
	} catch (blitz::error const&) {
		// Not an assignment, the command parsing below reports errors properly.
	}
	_pos = start;

	advance();
	auto type        = parse_type_suffix(name);
	auto struct_name = _struct_name;

	auto node                = std::make_unique<ast::call_statement>();
	node->where              = here(name);
	node->invocation         = std::make_unique<ast::call>();
	node->invocation->where  = here(name);
	node->invocation->name   = name.text;
	node->invocation->type   = type;
	node->invocation->struct_name = struct_name;

	if (is_symbol(tk(), "(")) {
		// Try `Name(Arg, ...)` first. If something follows the `)`, it's actually `Name (Expression)...`.
		size_t saved = _pos;
		advance();
		auto args = parse_arguments();
		expect_symbol(")");
		if (is_terminator(tk())) {
			node->invocation->arguments = std::move(args);
			into.push_back(std::move(node));
			return;
		}
		_pos = saved;
	}

	if (!is_terminator(tk())) {
		while (true) {
			node->invocation->arguments.push_back(parse_expression());
			if (is_symbol(tk(), ",")) {
				advance();
				continue;
			}
			break;
		}
	}
	into.push_back(std::move(node));
}

////////////////////////////////////////////////////////////////////////////////
// Expressions
////////////////////////////////////////////////////////////////////////////////
blitz::types::type blitz::parser::parse_type_suffix(blitz::token const& name)
{
	_struct_name.clear();
	auto const& next = tk();
	if (next.type == blitz::token::variant::SYMBOL) {
		if (!adjacent(name, next)) {
			return blitz::types::type::UNKNOWN;
		}
		if (next.text == "%") {
			advance();
			return blitz::types::type::INT32;
		} else if (next.text == "%%") {
			advance();
			return blitz::types::type::INT64;
		} else if (next.text == "#") {
			advance();
			return blitz::types::type::FLOAT32;
		} else if (next.text == "##") {
			advance();
			return blitz::types::type::FLOAT64;
		} else if (next.text == "$") {
			advance();
			return blitz::types::type::STRING;
		} else if (next.text == ".") {
			// `Name.TypeName`
			auto const& type_tk = tk(1);
			if ((type_tk.type != blitz::token::variant::TEXT) || !adjacent(next, type_tk)) {
				throw error(next, "Expected a type name after '.'.");
			}
			_struct_name = type_tk.text;
			advance();
			advance();
			return blitz::types::type::STRUCT;
		}
	} else if ((next.type == blitz::token::variant::SEPARATOR) && adjacent(name, next)) {
		// `Name:Type` is only a type if directly attached, and the type is a known one.
		auto const& type_tk = tk(1);
		if ((type_tk.type == blitz::token::variant::TEXT) && adjacent(next, type_tk)) {
			auto type = blitz::types::from_string(type_tk.text);
			if (type != blitz::types::type::UNKNOWN) {
				advance();
				advance();
				return type;
			}
		}
	}
	return blitz::types::type::UNKNOWN;
}

std::vector<blitz::ast::expression_ptr> blitz::parser::parse_arguments()
{
	std::vector<ast::expression_ptr> args;
	if (is_symbol(tk(), ")")) {
		return args;
	}
	while (true) {
		args.push_back(parse_expression());
		if (is_symbol(tk(), ",")) {
			advance();
			continue;
		}
		break;
	}
	return args;
}

blitz::ast::expression_ptr blitz::parser::make_binary(blitz::token const& at, ast::binary::op kind, ast::expression_ptr lhs, ast::expression_ptr rhs)
{
	auto node   = std::make_unique<ast::binary>();
	node->where = here(at);
	node->kind  = kind;
	node->lhs   = std::move(lhs);
	node->rhs   = std::move(rhs);
	return node;
}

blitz::ast::expression_ptr blitz::parser::parse_expression()
{
	return parse_or();
}

blitz::ast::expression_ptr blitz::parser::parse_or()
{
	auto lhs = parse_and();
	while (true) {
		auto op = tk();
		if (is_keyword(op, "or")) {
			advance();
			lhs = make_binary(op, ast::binary::op::OR, std::move(lhs), parse_and());
		} else if (is_keyword(op, "xor")) {
			advance();
			lhs = make_binary(op, ast::binary::op::XOR, std::move(lhs), parse_and());
		} else {
			return lhs;
		}
	}
}

blitz::ast::expression_ptr blitz::parser::parse_and()
{
	auto lhs = parse_not();
	while (is_keyword(tk(), "and")) {
		auto op = tk();
		advance();
		lhs = make_binary(op, ast::binary::op::AND, std::move(lhs), parse_not());
	}
	return lhs;
}

blitz::ast::expression_ptr blitz::parser::parse_not()
{
	if (is_keyword(tk(), "not")) {
		auto op = tk();
		advance();
		auto node     = std::make_unique<ast::unary>();
		node->where   = here(op);
		node->kind    = ast::unary::op::NOT;
		node->operand = parse_not();
		return node;
	}
	return parse_comparison();
}

blitz::ast::expression_ptr blitz::parser::parse_comparison()
{
	auto lhs = parse_shift();
	while (true) {
		auto op = tk();
		if (op.type != blitz::token::variant::SYMBOL) {
			return lhs;
		}
		ast::binary::op kind;
		if ((op.text == "=") || (op.text == "==")) {
			kind = ast::binary::op::EQUAL;
		} else if (op.text == "<>") {
			kind = ast::binary::op::NOT_EQUAL;
		} else if (op.text == "<") {
			kind = ast::binary::op::LESS;
		} else if (op.text == "<=") {
			kind = ast::binary::op::LESS_EQUAL;
		} else if (op.text == ">") {
			kind = ast::binary::op::GREATER;
		} else if (op.text == ">=") {
			kind = ast::binary::op::GREATER_EQUAL;
		} else {
			return lhs;
		}
		advance();
		lhs = make_binary(op, kind, std::move(lhs), parse_shift());
	}
}

blitz::ast::expression_ptr blitz::parser::parse_shift()
{
	auto lhs = parse_additive();
	while (true) {
		auto op = tk();
		ast::binary::op kind;
		if (is_keyword(op, "shl")) {
			kind = ast::binary::op::SHL;
		} else if (is_keyword(op, "shr")) {
			kind = ast::binary::op::SHR;
		} else if (is_keyword(op, "sar")) {
			kind = ast::binary::op::SAR;
		} else {
			return lhs;
		}
		advance();
		lhs = make_binary(op, kind, std::move(lhs), parse_additive());
	}
}

blitz::ast::expression_ptr blitz::parser::parse_additive()
{
	auto lhs = parse_multiplicative();
	while (is_symbol(tk(), "+") || is_symbol(tk(), "-")) {
		auto op = tk();
		advance();
		lhs = make_binary(op, (op.text == "+") ? ast::binary::op::ADD : ast::binary::op::SUBTRACT, std::move(lhs), parse_multiplicative());
	}
	return lhs;
}

blitz::ast::expression_ptr blitz::parser::parse_multiplicative()
{
	auto lhs = parse_power();
	while (true) {
		auto op = tk();
		ast::binary::op kind;
		if (is_symbol(op, "*")) {
			kind = ast::binary::op::MULTIPLY;
		} else if (is_symbol(op, "/")) {
			kind = ast::binary::op::DIVIDE;
		} else if (is_keyword(op, "mod")) {
			kind = ast::binary::op::MODULO;
		} else {
			return lhs;
		}
		advance();
		lhs = make_binary(op, kind, std::move(lhs), parse_power());
	}
}

blitz::ast::expression_ptr blitz::parser::parse_power()
{
	auto lhs = parse_unary();
	while (is_symbol(tk(), "^")) {
		auto op = tk();
		advance();
		lhs = make_binary(op, ast::binary::op::POWER, std::move(lhs), parse_unary());
	}
	return lhs;
}

blitz::ast::expression_ptr blitz::parser::parse_unary()
{
	auto op = tk();
	if (is_keyword(op, "new") || is_keyword(op, "first") || is_keyword(op, "last")) {
		advance();
		auto type_tk = tk();
		if ((type_tk.type != blitz::token::variant::TEXT) || reserved.count(lower(type_tk.text))) {
			throw error(type_tk, blitz::format("Unexpected %s, expected a type name.", type_tk.to_string().c_str()));
		}
		advance();
		if (is_keyword(op, "new")) {
			auto node       = std::make_unique<ast::new_object>();
			node->where     = here(op);
			node->type_name = type_tk.text;
			return node;
		}
		auto node       = std::make_unique<ast::list_end>();
		node->where     = here(op);
		node->type_name = type_tk.text;
		node->last      = is_keyword(op, "last");
		return node;
	} else if (is_keyword(op, "before") || is_keyword(op, "after")) {
		advance();
		auto node    = std::make_unique<ast::list_neighbor>();
		node->where  = here(op);
		node->after  = is_keyword(op, "after");
		node->object = parse_unary();
		return node;
	}
	if (is_symbol(op, "-") || is_symbol(op, "+") || is_symbol(op, "~")) {
		advance();
		auto node     = std::make_unique<ast::unary>();
		node->where   = here(op);
		node->kind    = (op.text == "-") ? ast::unary::op::NEGATE : ((op.text == "+") ? ast::unary::op::PLUS : ast::unary::op::COMPLEMENT);
		node->operand = parse_unary();
		return node;
	}
	return parse_primary();
}

blitz::ast::expression_ptr blitz::parser::parse_number(blitz::token const& token)
{
	auto node   = std::make_unique<ast::literal>();
	node->where = here(token);

	if (token.type == blitz::token::variant::REAL) {
		node->kind = ast::literal::variant::REAL;
		errno      = 0;
		node->f    = strtod(token.text.c_str(), nullptr);
		if (errno == ERANGE) {
			throw error(token, blitz::format("Real '%s' is not representable on this system.", token.text.c_str()));
		}
		return node;
	}

	std::string text = token.text;
	bool        is_unsigned = false;
	if (!text.empty() && ((text.back() == 'u') || (text.back() == 'U'))) {
		is_unsigned = true;
		text.pop_back();
	}
	int base = 10;
	if ((text.length() >= 2) && (text[0] == '0') && ((text[1] == 'x') || (text[1] == 'X'))) {
		base = 16;
		text = text.substr(2);
	} else if ((text.length() >= 2) && (text[0] == '0') && ((text[1] == 'b') || (text[1] == 'B'))) {
		base = 2;
		text = text.substr(2);
	}
	if (text.empty()) {
		throw error(token, blitz::format("Integer '%s' has no digits.", token.text.c_str()));
	}

	errno        = 0;
	uintmax_t ui = strtoull(text.c_str(), nullptr, base);
	if (errno == ERANGE) {
		throw error(token, blitz::format("Integer '%s' is not representable on this system.", token.text.c_str()));
	}
	if (is_unsigned || (ui > uintmax_t(INTMAX_MAX))) {
		node->kind = ast::literal::variant::UNSIGNED_INTEGER;
		node->u    = ui;
	} else {
		node->kind = ast::literal::variant::INTEGER;
		node->i    = intmax_t(ui);
	}
	return node;
}

// Field access (`Object\Field`) and array elements (`Array[Index]`) that follow something.
blitz::ast::expression_ptr blitz::parser::parse_postfix(ast::expression_ptr base)
{
	while (true) {
		if (is_symbol(tk(), "\\")) {
			auto slash = tk();
			advance();
			auto field = tk();
			if (field.type != blitz::token::variant::TEXT) {
				throw error(field, blitz::format("Unexpected %s, expected a field name.", field.to_string().c_str()));
			}
			advance();
			parse_type_suffix(field); // The field already has a type, the suffix is optional.

			auto node    = std::make_unique<ast::field_access>();
			node->where  = here(slash);
			node->object = std::move(base);
			node->name   = field.text;
			base         = std::move(node);
		} else if (is_symbol(tk(), "[")) {
			auto bracket = tk();
			advance();
			auto node   = std::make_unique<ast::index_access>();
			node->where = here(bracket);
			node->base  = std::move(base);
			node->index = parse_expression();
			expect_symbol("]");
			base = std::move(node);
		} else {
			return base;
		}
	}
}

blitz::ast::expression_ptr blitz::parser::parse_primary()
{
	auto token = tk();
	switch (token.type) {
	case blitz::token::variant::INTEGER:
	case blitz::token::variant::REAL:
		advance();
		return parse_number(token);
	case blitz::token::variant::STRING: {
		advance();
		auto node   = std::make_unique<ast::literal>();
		node->where = here(token);
		node->kind  = ast::literal::variant::STRING;
		node->text  = token.text;
		return node;
	}
	case blitz::token::variant::SYMBOL: {
		if (token.text == "(") {
			advance();
			auto inner = parse_expression();
			expect_symbol(")");
			return parse_postfix(std::move(inner));
		}
		break;
	}
	case blitz::token::variant::TEXT: {
		std::string word = lower(token.text);
		if ((word == "true") || (word == "false") || (word == "null")) {
			advance();
			auto node   = std::make_unique<ast::literal>();
			node->where = here(token);
			node->kind  = (word == "null") ? ast::literal::variant::NULLPTR : ast::literal::variant::INTEGER;
			node->i     = (word == "true") ? 1 : 0;
			return node;
		} else if (reserved.count(word) || unsupported.count(word)) {
			throw error(token, blitz::format("Unexpected '%s' in expression.", token.text.c_str()));
		}

		advance();
		auto type        = parse_type_suffix(token);
		auto struct_name = _struct_name;
		if ((word == "object") && (type == blitz::types::type::STRUCT)) {
			// Object.TypeName(Handle)
			expect_symbol("(");
			auto node        = std::make_unique<ast::object_from_handle>();
			node->where      = here(token);
			node->type_name  = struct_name;
			node->handle     = parse_expression();
			expect_symbol(")");
			return parse_postfix(std::move(node));
		}
		if (is_symbol(tk(), "(")) {
			advance();
			auto node         = std::make_unique<ast::call>();
			node->where       = here(token);
			node->name        = token.text;
			node->type        = type;
			node->struct_name = struct_name;
			node->arguments   = parse_arguments();
			expect_symbol(")");
			return parse_postfix(std::move(node));
		}
		auto node         = std::make_unique<ast::reference>();
		node->where       = here(token);
		node->name        = token.text;
		node->type        = type;
		node->struct_name = struct_name;
		return parse_postfix(std::move(node));
	}
	default:
		break;
	}
	throw error(token, blitz::format("Unexpected %s, expected an expression.", token.to_string().c_str()));
}
